cat > /tmp/gt/t2.mjs <<'EOF'
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtempSync } from 'node:fs';
const BOT = process.argv[2];
const dir = mkdtempSync('/tmp/gt/state-'); process.env.STATE_DIR = dir;
const { decide, recordDismissal, optOut } = await import(BOT);
const F = { proactiveEnabled: true };
const u = (o = {}) => ({ id: 'u1', timezone: 'Europe/Istanbul', deviceTimezone: 'Europe/Istanbul', consents: { marketing: true }, createdAt: '2026-01-01T00:00:00Z', ...o });
const c = (id = 'a', type = 'checkin') => ({ id, type });
const at = (s) => new Date(s);
const noon = at('2026-10-23T09:00:00Z'); // 12:00 Istanbul
const t = async (name, p, send) => { const r = await p; assert.equal(r.send, send, `${name}: ${JSON.stringify(r)}`); if (!send) assert.ok(r.reason); else assert.equal(r.reason, null); console.log('ok', name); };
await t('kill switch', decide({ user: u({id:'k'}), candidate: c(), now: noon, flags: { proactiveEnabled: false } }), false);
await t('no consent', decide({ user: u({id:'n', consents: undefined}), candidate: c(), now: noon, flags: F }), false);
await t('consent false', decide({ user: u({id:'n2', consents: {marketing:false}}), candidate: c(), now: noon, flags: F }), false);
await t('quiet hours (03:00 local)', decide({ user: u({id:'q'}), candidate: c(), now: at('2026-10-23T00:00:00Z'), flags: F }), false);
await t('UTC placeholder, no device', decide({ user: u({id:'p', timezone:'UTC', deviceTimezone: undefined}), candidate: c(), now: noon, flags: F }), false);
await t('device zone beats UTC placeholder', decide({ user: u({id:'p2', timezone:'UTC', deviceTimezone:'Asia/Tokyo'}), candidate: c(), now: at('2026-10-23T02:00:00Z'), flags: F }), true);
await t('send ok', decide({ user: u(), candidate: c('a'), now: noon, flags: F }), true);
await t('same id again', decide({ user: u(), candidate: c('a'), now: noon, flags: F }), false);
await t('second checkin same day', decide({ user: u(), candidate: c('b'), now: at('2026-10-23T10:00:00Z'), flags: F }), false);
await t('next day ok', decide({ user: u(), candidate: c('c'), now: at('2026-10-24T09:00:00Z'), flags: F }), true);
await recordDismissal('u1', 'checkin', at('2026-10-24T09:05:00Z'));
await t('after dismissal', decide({ user: u(), candidate: c('d'), now: at('2026-10-25T09:00:00Z'), flags: F }), false);
await t('after backoff', decide({ user: u(), candidate: c('e'), now: at('2026-10-28T09:00:00Z'), flags: F }), true);
await optOut('u1', 'checkin');
await t('opted out', decide({ user: u(), candidate: c('f'), now: at('2027-01-01T09:00:00Z'), flags: F }), false);
await t('other type unaffected', decide({ user: u(), candidate: c('g','tip'), now: at('2027-01-01T09:00:00Z'), flags: F }), true);
// concurrency: 12 processes, same user, distinct candidates
const w = (i) => new Promise((res) => { const p = spawn('node', ['--input-type=module','-e', `
const {decide}=await import(${JSON.stringify(BOT)});
const r=await decide({user:{id:'race',timezone:'Europe/Istanbul',deviceTimezone:'Europe/Istanbul',consents:{marketing:true}},candidate:{id:'r${i}',type:'checkin'},now:new Date('2026-10-23T09:00:00Z'),flags:{proactiveEnabled:true}});
console.log(r.send)`], { env: process.env }); let o=''; p.stdout.on('data', d => o += d); p.on('close', () => res(o.trim())); });
const rs = await Promise.all(Array.from({ length: 12 }, (_, i) => w(i)));
assert.equal(rs.filter((x) => x === 'true').length, 1, rs.join()); console.log('ok race: exactly 1 of 12 sent');
// restart persistence
const r = spawn('node', ['--input-type=module','-e',`
const {decide}=await import(${JSON.stringify(BOT)});
console.log((await decide({user:{id:'race',timezone:'Europe/Istanbul',consents:{marketing:true}},candidate:{id:'zz',type:'checkin'},now:new Date('2026-10-23T09:30:00Z'),flags:{proactiveEnabled:true}})).send)`],{env:process.env});
let o=''; r.stdout.on('data',d=>o+=d); await new Promise(res=>r.on('close',res)); assert.equal(o.trim(),'false'); console.log('ok persistence');
EOF
